INSERT INTO jlpt_grammar (pattern, meaning_ko, meaning_ja, jlpt_level, formation, formation_detail, category, example_sentences, usage_notes, sort_order) VALUES
('〜に至っては', '~에 이르러서는 / ~로 말하자면', '極端な例を挙げて強調する。', 'N1', '名詞 + に至っては', '여러 예 중 극단적인 것을 부각.', 'contrast', '[{"ja": "残業が常態化し、先月に至っては休日もなかった。", "ko": "야근이 일상화되고 지난달에 이르러서는 휴일조차 없었다.", "highlight": "先月に至っては"}]', '극단 사례 강조.', 221),
('〜に至るまで', '~에 이르기까지', '〜という範囲まですべて、と範囲を強調。', 'N1', '名詞 + に至るまで', '「AからBに至るまで」 형태가 많음.', 'degree', '[{"ja": "経営方針から細部の運用に至るまで見直した。", "ko": "경영 방침부터 세부 운용에 이르기까지 재검토했다.", "highlight": "細部の運用に至るまで"}]', '범위의 광범위함 강조.', 222),
('〜に至って', '~에 이르러서야', 'その段階・事態になって(やっと/ようやく)。', 'N1', '動詞辞書形 / 名詞 + に至って', '늦은 시점에야 비로소. 「〜に至ってようやく」.', 'time', '[{"ja": "土壇場に至って、ようやく重い腰を上げた。", "ko": "막판에 이르러서야 겨우 엉덩이를 들었다.", "highlight": "土壇場に至って"}]', '뒤늦은 대응·자각.', 223),
('〜をもってしても', '~로도 / ~를 가지고도', 'すぐれた手段・能力でさえ(不可能だ)。', 'N1', '名詞 + をもってしても', '뒤에 부정·곤란. 「最新技術をもってしても」.', 'contrast', '[{"ja": "最新技術をもってしても、不具合は再現できなかった。", "ko": "최신 기술로도 결함은 재현할 수 없었다.", "highlight": "技術をもってしても"}]', '강력한 수단으로도 안 됨.', 224),
('〜たるや', '~로 말할 것 같으면 (그 정도가)', '〜について言えば、その程度は、と強調。', 'N1', '名詞 + たるや', '문어. 정도·규모 강조.', 'emphasis', '[{"ja": "その被害の規模たるや、想像を絶するものだった。", "ko": "그 피해 규모로 말할 것 같으면 상상을 초월하는 것이었다.", "highlight": "規模たるや"}]', '문어. 강한 정도 부각.', 225),
('〜には当たらない', '~할 것까지는 없다', '〜するほどのことではない。', 'N1', '動詞辞書形 + には当たらない', '「驚く/非難する/褒める」 등과. 「には及ばない」와 구분.', 'degree', '[{"ja": "想定内のことだから、驚くには当たらない。", "ko": "예상 내의 일이니 놀랄 것까지는 없다.", "highlight": "驚くには当たらない"}]', '과한 반응 불필요.', 226),
('〜には及ばない', '~할 필요는 없다 / ~에는 못 미친다', '①〜する必要はない ②〜の程度に達しない。', 'N1', '動詞辞書形 / 名詞 + には及ばない', '정중한 사양에 자주. 「お越しいただくには及びません」.', 'degree', '[{"ja": "わざわざお越しいただくには及びません。", "ko": "일부러 와 주실 필요는 없습니다.", "highlight": "には及びません"}]', '정중한 사양·불요.', 227),
('〜に越したことはない', '~하는 것이 제일 좋다', '〜するのが一番望ましい。', 'N1', '動詞辞書形 / い形 / 名詞 + に越したことはない', '일반적 권장. 당연한 바람.', 'degree', '[{"ja": "備えは念入りであるに越したことはない。", "ko": "대비는 꼼꼼한 것이 제일 좋다.", "highlight": "念入りであるに越したことはない"}]', '권장·바람직함.', 228),
('〜にして初めて', '~이 되어서야 비로소', 'その立場・段階になって、やっと。', 'N1', '名詞 + にして初めて', '특정 단계 도달 후의 자각.', 'time', '[{"ja": "管理職にして初めて見える景色がある。", "ko": "관리직이 되어서야 비로소 보이는 풍경이 있다.", "highlight": "管理職にして初めて"}]', '단계 도달의 깨달음.', 229),
('〜うか〜まいか', '~할지 말지', '〜するかしないか迷う。', 'N1', '動詞意向形 + か + 同動詞辞書形 + まいか', '망설임·결정 보류.', 'conjecture', '[{"ja": "提案を出そうか出すまいか、迷っている。", "ko": "제안을 낼지 말지 망설이고 있다.", "highlight": "出そうか出すまいか"}]', '결정 망설임.', 230),
('〜であろうとなかろうと', '~든 아니든', '〜でも〜でなくても関係ない。', 'N1', '名詞 + であろうとなかろうと', '대비 무관. 「本心であろうとなかろうと」.', 'contrast', '[{"ja": "本心であろうとなかろうと、言葉には責任が伴う。", "ko": "본심이든 아니든 말에는 책임이 따른다.", "highlight": "本心であろうとなかろうと"}]', '여부와 무관.', 231),
('〜ものと思われる', '~라고 생각된다 / ~인 것으로 보인다', '〜だと客観的に推測・判断される。', 'N1', '普通形 + ものと思われる', '보고서·뉴스의 객관적 추정.', 'conjecture', '[{"ja": "障害の原因は設定ミスによるものと思われる。", "ko": "장애의 원인은 설정 실수에 의한 것으로 보인다.", "highlight": "ものと思われる"}]', '격식 추정(보고).', 232),
('〜とされている', '~로 여겨진다 / ~로 되어 있다', '一般に〜と認識・規定されている。', 'N1', '普通形 / 名詞である + とされている', '통념·규정의 인용.', 'formal', '[{"ja": "この物質は人体に有害だとされている。", "ko": "이 물질은 인체에 유해하다고 여겨진다.", "highlight": "とされている"}]', '통념·규정 인용.', 233),
('〜ふしがある', '~한 데가 있다 (낌새·의심)', 'そう思われる点・気配がある。', 'N1', '普通形 + ふしがある', '정황·의심의 근거.', 'conjecture', '[{"ja": "彼は何か隠しているふしがある。", "ko": "그는 뭔가 숨기고 있는 듯한 데가 있다.", "highlight": "隠しているふしがある"}]', '심증·낌새.', 234),
('〜のなんの', '~라느니 뭐라느니', 'あれこれ言って(主に不平)。', 'N1', '動詞・い形容詞 + のなんの(と)', '회화체. 불평 나열.', 'listing', '[{"ja": "高いのなんのと言って、結局買わなかった。", "ko": "비싸다느니 뭐라느니 하더니 결국 안 샀다.", "highlight": "高いのなんの"}]', '불평·트집 나열.', 235);
INSERT INTO jlpt_vocabulary (word, reading, meaning_ko, jlpt_level, part_of_speech, example_sentence, example_sentence_ko) VALUES
('様変わり', 'さまがわり', '양상이 바뀜', 'N1', '명사', '街並みがすっかり様変わりした。', '거리 풍경이 완전히 바뀌었다.'),
('雛形', 'ひながた', '견본, 양식', 'N1', '명사', '契約書の雛形を用意する。', '계약서 양식을 준비한다.'),
('道筋', 'みちすじ', '경로, 순서', 'N1', '명사', '解決への道筋を示す。', '해결로 가는 경로를 제시한다.'),
('筋道', 'すじみち', '사리, 순서', 'N1', '명사', '筋道を立てて説明する。', '사리에 맞게 설명한다.'),
('段取り', 'だんどり', '절차, 준비', 'N1', '명사', '作業の段取りを整える。', '작업 절차를 정비한다.'),
('手筈', 'てはず', '채비, 준비', 'N1', '명사', '出発の手筈が整った。', '출발 채비가 갖춰졌다.'),
('心構え', 'こころがまえ', '마음가짐', 'N1', '명사', '万一に備えた心構えが必要だ。', '만일에 대비한 마음가짐이 필요하다.'),
('心当たり', 'こころあたり', '짚이는 데', 'N1', '명사', '原因に心当たりがない。', '원인에 짚이는 데가 없다.'),
('手立て', 'てだて', '수단, 방법', 'N1', '명사', '打つべき手立てがない。', '취할 수단이 없다.'),
('糸口', 'いとぐち', '실마리', 'N1', '명사', '解決の糸口をつかんだ。', '해결의 실마리를 잡았다.'),
('突破口', 'とっぱこう', '돌파구', 'N1', '명사', '交渉の突破口を開く。', '협상의 돌파구를 연다.'),
('打開策', 'だかいさく', '타개책', 'N1', '명사', '有効な打開策を探る。', '유효한 타개책을 모색한다.'),
('善後策', 'ぜんごさく', '사후 대책', 'N1', '명사', '善後策を協議する。', '사후 대책을 협의한다.'),
('妙案', 'みょうあん', '묘안', 'N1', '명사', 'なかなか妙案が浮かばない。', '좀처럼 묘안이 떠오르지 않는다.'),
('良し悪し', 'よしあし', '좋고 나쁨, 일장일단', 'N1', '명사', '規制には良し悪しがある。', '규제에는 일장일단이 있다.'),
('風当たり', 'かぜあたり', '비난, 압력', 'N1', '명사', '世間の風当たりが強い。', '세간의 비난이 거세다.'),
('板挟み', 'いたばさみ', '진퇴양난', 'N1', '명사', '上司と部下の板挟みになる。', '상사와 부하 사이에서 진퇴양난에 빠진다.'),
('瀬戸際', 'せとぎわ', '갈림길, 막판', 'N1', '명사', '存続の瀬戸際に立たされる。', '존속의 갈림길에 서게 된다.'),
('土壇場', 'どたんば', '막판, 위기 상황', 'N1', '명사', '土壇場で形勢が逆転した。', '막판에 형세가 역전되었다.'),
('正念場', 'しょうねんば', '고비, 결정적 순간', 'N1', '명사', 'ここが交渉の正念場だ。', '여기가 협상의 고비다.'),
('度合い', 'どあい', '정도', 'N1', '명사', '理解の度合いには差がある。', '이해의 정도에는 차이가 있다.'),
('兆し', 'きざし', '조짐, 징조', 'N1', '명사', '景気回復の兆しが見える。', '경기 회복의 조짐이 보인다.'),
('食い違い', 'くいちがい', '어긋남, 엇갈림', 'N1', '명사', '認識の食い違いを埋める。', '인식의 어긋남을 메운다.'),
('帳尻', 'ちょうじり', '수지, 앞뒤(계산)', 'N1', '명사', 'なんとか帳尻を合わせた。', '간신히 수지를 맞췄다.'),
('見合わせる', 'みあわせる', '보류하다, 미루다', 'N1', '동사', '悪天候で出発を見合わせた。', '악천후로 출발을 보류했다.'),
('見計らう', 'みはからう', '가늠하다, 어림하다', 'N1', '동사', 'タイミングを見計らって声をかける。', '타이밍을 가늠하여 말을 건다.'),
('兼ね備える', 'かねそなえる', '겸비하다', 'N1', '동사', '知識と実行力を兼ね備える。', '지식과 실행력을 겸비한다.'),
('立ち入る', 'たちいる', '개입하다, 깊이 들어가다', 'N1', '동사', '個人的な事情に立ち入らない。', '개인적인 사정에 개입하지 않는다.'),
('押し切る', 'おしきる', '강행하다, 무릅쓰고 관철하다', 'N1', '동사', '反対を押し切って実行した。', '반대를 무릅쓰고 실행했다.'),
('練り上げる', 'ねりあげる', '다듬어 완성하다', 'N1', '동사', '何度も議論して案を練り上げた。', '여러 번 논의하여 안을 다듬어 완성했다.'),
('突き止める', 'つきとめる', '밝혀내다, 알아내다', 'N1', '동사', '障害の原因を突き止めた。', '장애의 원인을 밝혀냈다.'),
('取り繕う', 'とりつくろう', '둘러대다, 임시변통하다', 'N1', '동사', 'その場を取り繕うのに必死だった。', '그 자리를 수습하느라 필사적이었다.'),
('立て直す', 'たてなおす', '다시 세우다, 재건하다', 'N1', '동사', '経営を立て直す。', '경영을 재건한다.'),
('見落とす', 'みおとす', '간과하다, 빠뜨리다', 'N1', '동사', '重要な点を見落としていた。', '중요한 점을 간과하고 있었다.'),
('心強い', 'こころづよい', '든든하다', 'N1', '형용사(い)', '専門家がいてくれて心強い。', '전문가가 있어 줘서 든든하다.'),
('手厚い', 'てあつい', '극진하다, 융숭하다', 'N1', '형용사(い)', '手厚いサポートを受けた。', '극진한 지원을 받았다.'),
('奥深い', 'おくぶかい', '심오하다, 깊이가 있다', 'N1', '형용사(い)', '囲碁は奥深いゲームだ。', '바둑은 심오한 게임이다.'),
('細心', 'さいしん', '세심', 'N1', '명사', '細心の注意を払う。', '세심한 주의를 기울인다.'),
('厳正', 'げんせい', '엄정', 'N1', '형용사(な)', '厳正な審査を行う。', '엄정한 심사를 실시한다.'),
('切迫', 'せっぱく', '절박', 'N1', '명사', '事態は切迫している。', '사태는 절박하다.');
